"use client";
/* Planet, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Planet(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("planet"); }, []);
  return React.createElement("piix-planet", piixAttrs(props));
}

export default Planet;
